use crate::{scene::Scene,prepared::PreparedMesh,pick_sources::{Mode,Part,Target,Sources},cap_gpu_tests::{renderer,pixels_at,at,wait}};
use session_rust::{Mesh,Point,Color,Session,Xform,proto};use prost::Message;use std::rc::Rc;
fn grid(n:usize)->Mesh{let mut p=Vec::new();for y in 0..=n{for x in 0..=n{p.push(Point::new(-900.+1800.*x as f64/n as f64,-650.+1300.*y as f64/n as f64,0.));}}let mut f=Vec::new();for y in 0..n{for x in 0..n{let a=y*(n+1)+x;f.extend([vec![a,a+1,a+n+2],vec![a,a+n+2,a+n+1]]);}}let mut m=Mesh::from_vertices_and_faces(p,f);m.set_objectcolor(Color::new(0.2,0.4,0.6,1.));m}
fn scene(m:Mesh)->Scene{let mut s=Scene::empty();s.insert(PreparedMesh::new(m).unwrap()).unwrap();s}
fn camera()->crate::camera::Camera{let mut c=crate::camera_defaults_tests::top_fixture();c.distance=3000.;c.radius=1500.;c.aspect=4./3.;c}
fn matrix(c:&crate::camera::Camera)->[f32;16]{let mut m=c.uniform();m[12]+=m[15]*0.9/160.;m[13]-=m[15]*0.9/120.;m}
fn projected(m:[f32;16],p:[f64;3])->[f64;2]{let c:[f64;4]=std::array::from_fn(|i|m[12+i]as f64+(0..3).map(|j|m[j*4+i]as f64*p[j]).sum::<f64>());[(c[0]/c[3]+1.)*160.,(1.-c[1]/c[3])*120.]}
fn source(s:&Scene)->(Vec<proto::Session>,serde_json::Value){let b=crate::archive::Bundle::decode(&crate::scene_archive::save(s).unwrap()).unwrap();(b.documents.iter().map(|v|proto::Session::decode(v.as_slice()).unwrap()).collect(),serde_json::to_value(b.metadata).unwrap())}
fn export(name:&str,s:&Scene,image:&[u8]){if let Some(root)=std::env::var_os("VIEWER_MESH_DENSITY_PROOF_DIR"){use std::io::Write;let p=std::path::Path::new(&root);std::fs::create_dir_all(p).unwrap();std::fs::write(p.join(format!("{name}.session")),crate::scene_archive::save(s).unwrap()).unwrap();let mut f=std::fs::File::create(p.join(format!("{name}.ppm"))).unwrap();write!(f,"P6\n320 240\n255\n").unwrap();for p in image.chunks_exact(4){f.write_all(&p[..3]).unwrap();}}}
fn pick(g:&mut super::Renderer,s:&Scene,m:[f32;16],p:[f64;3],mode:Mode)->Option<Target>{g.set_pick_mode(mode);g.request_pick(super::contact_feature_tests::project(m,p),m).unwrap();wait(g);g.take_pick(m).unwrap().unwrap().and_then(|v|g.resolve_pick(s,v))}
fn expected(s:&Scene,m:[f32;16])->[u8;3]{let mut rgb=[51f64,102.,153.];let row=&s.objects()[0];for &address in &row.mesh.parts.dots{let p=row.mesh.parts.endpoints[address as usize/2][address as usize%2];let p=row.model.transform_point(&Point::new(p[0],p[1],p[2]));let q=projected(m,[p[0],p[1],p[2]]);let coverage=(1.-(q[0]-160.5).hypot(q[1]-120.5)).clamp(0.,1.);for v in &mut rgb{*v=(25.5*coverage+*v*(1.-coverage)).round();}}rgb.map(|v|v as u8)}
#[test]
fn actual_original_dense_dots_share_color_and_pick_coverage_at_both_densities(){
 let s=scene(grid(128));let original=source(&s);let owner=s.objects()[0].id;assert_eq!(s.objects()[0].mesh.parts.dots.len(),16641);let wanted=(1800f32.hypot(1300.))/(16641f32).sqrt();assert!((s.objects()[0].mesh.spacing-wanted).abs()<1e-5);let mut g=renderer(&s);g.set_opacity(1.);g.set_lighting(false,false);let uploads=g.stats()[0];let mut c=camera();for distance in [3000.,1500.]{c.distance=distance;for projection in [crate::camera::Projection::Orthographic,crate::camera::Projection::Perspective]{c.projection=projection;let m=matrix(&c);for density in [1.,2.]{g.set_density(density);let image=pixels_at(&g,m);let rgb=expected(&s,m);assert!(at(&image,160,120)[..3].iter().zip(rgb).all(|(a,b)|a.abs_diff(b)<=2),"Actual full-source dots use the independently composited half-physical-pixel footprint");assert_eq!(g.point_usage()[0],16641);assert_eq!(g.markers.clipping_bytes(),[4,4]);assert_eq!(pick(&mut g,&s,m,[0.,0.,0.],Mode::Object),Some(Target{owner,part:Part::Object}));assert_eq!(pick(&mut g,&s,m,[0.,0.,0.],Mode::Control),None);assert!(pixels_at(&g,m)==image);assert_eq!(g.stats()[0],uploads);assert_eq!(source(&s),original);let name=if projection==crate::camera::Projection::Orthographic{if density==1.{"dense-dpr1"}else{"dense-dpr2"}}else{"dense-perspective"};if projection==crate::camera::Projection::Orthographic||density==2.{export(&format!("{name}{}",if distance==1500.{"-readable"}else{""}),&s,&image);}}}}
 g.set_density(2.);let before=pixels_at(&g,matrix(&c));g.markers.use_legacy_fixture();assert!(pixels_at(&g,matrix(&c))==before,"The real retained legacy marker path shares the exact same spacing/coverage rule");
}
#[test]
fn original_points_and_active_controls_keep_their_positive_css_sizes(){
 let mut s=scene(grid(1));let owner=s.objects()[0].id;let mut p=Point::new(0.,0.,20.);p.width=9.;p.pointcolor=Color::new(0.8,0.1,0.2,1.);let point=s.insert_point(crate::marker::PreparedPoint::new(Rc::new(p)).unwrap()).unwrap();s.owner_controls(owner).unwrap();let original=source(&s);let prepared=Sources::new(&s).unwrap();assert!(prepared.mesh_markers.iter().all(|m|m.diameter<0.));assert_eq!(s.points()[0].marker().diameter,9.);assert!(s.control_markers().iter().all(|m|m.display.diameter==7.));let mut g=renderer(&s);g.set_opacity(1.);g.set_lighting(false,false);let mut c=camera();for projection in[crate::camera::Projection::Orthographic,crate::camera::Projection::Perspective]{c.projection=projection;let mut m=c.uniform();m[12]+=m[15]/320.;m[13]-=m[15]/240.;for density in[1.,2.]{g.set_density(density);let image=pixels_at(&g,m);assert_eq!(at(&image,160,120),[204,26,51,255]);assert_eq!(g.point_usage()[0],9);assert_eq!(g.markers.clipping_bytes(),[4,4]);assert_eq!(pick(&mut g,&s,m,[0.,0.,20.],Mode::Object),Some(Target{owner:point,part:Part::Object}));let control=pick(&mut g,&s,m,[-900.,-650.,0.],Mode::Control).unwrap();assert_eq!(control.owner,owner);assert!(matches!(control.part,Part::SourceControl(_)));assert!(pixels_at(&g,m)==image);assert_eq!(source(&s),original);if projection==crate::camera::Projection::Orthographic&&density==2.{export("explicit-point-controls",&s,&image);}}}
 let mut box_mesh=Mesh::new();for(i,p)in[[-900.,-650.,-100.],[900.,-650.,-100.],[900.,650.,-100.],[-900.,650.,-100.],[-900.,-650.,100.],[900.,-650.,100.],[900.,650.,100.],[-900.,650.,100.]].into_iter().enumerate(){box_mesh.add_vertex(Point::new(p[0],p[1],p[2]),Some(i));}for(face,ring)in[(17,vec![0,3,2,1]),(93,vec![4,5,6,7]),(125,vec![0,4,7,3]),(302,vec![1,2,6,5]),(456,vec![0,1,5,4]),(9004,vec![3,7,6,2])]{box_mesh.add_face(ring,Some(face));}box_mesh.set_objectcolor(Color::new(0.2,0.4,0.6,1.));box_mesh.set_linecolors(vec![],[vec![41.;4],vec![1.;8]].concat());let s=scene(box_mesh);g.set_scene(&s,None);c.projection=crate::camera::Projection::Perspective;let m=c.uniform();let edge=projected(m,[-900.,0.,100.]);let image=pixels_at(&g,m);assert_eq!(at(&image,edge[0].floor()as usize-8,edge[1].floor()as usize),[255,255,255,255],"Existing shared geometric visibility already hides rear edges; no redundant neighbor-normal buffer is needed for this opaque case");export("hidden-rear-border",&s,&image);
}
#[test]
fn spacing_survives_source_release_shared_placement_and_camera_updates(){
 let mesh=grid(16);let mut document=Session::new("Shared density source");document.add_mesh(mesh,None);let bytes=document.to_proto().encode_to_vec();let mut e=crate::editor::Editor::default();e.apply(crate::editor::Action::ReplaceAt(bytes.clone(),Rc::new(crate::reload_url::ReloadUrl::new("test:mesh-density".into())))).unwrap();let owner=e.scene.objects()[0].id;let display=Rc::clone(&e.scene.objects()[0].mesh);let weak=Rc::downgrade(e.scene.objects()[0].geometry().unwrap());let spacing=display.spacing;assert!(spacing>0.);let original=source(&e.scene);let mut g=renderer(&e.scene);g.set_opacity(1.);g.set_density(2.);let mut c=camera();let m=matrix(&c);let before=pixels_at(&g,m);let uploads=g.stats()[0];for _ in 0..2{c.distance*=1.1;pixels_at(&g,matrix(&c));c.distance/=1.1;assert!(pixels_at(&g,matrix(&c))==before);assert_eq!(g.stats()[0],uploads);assert_eq!(e.scene.objects()[0].mesh.spacing,spacing);}e.apply(crate::editor::Action::UnloadSources).unwrap();assert!(weak.upgrade().is_none());assert!(Rc::ptr_eq(&display,&e.scene.objects()[0].mesh));g.set_scene(&e.scene,None);assert!(pixels_at(&g,m)==before);assert_eq!(g.stats()[0],uploads);let keys=e.reload_keys();e.hydrate(keys.into_iter().map(|k|(k,bytes.clone())).collect()).unwrap();assert_eq!(source(&e.scene),original);
 let mesh=grid(16);let guid=mesh.guid().to_owned();let mut proto=crate::instance_specimen::message();proto.definitions.as_mut().unwrap().meshes=vec![mesh.to_proto()];for row in &mut proto.objects.as_mut().unwrap().instances{row.definition_guid=guid.clone();row.xform=None;row.flags=0;}proto.xforms=vec![session_rust::proto::XformEntry{guid:"first".into(),xform:Some(Xform::translation(-1800.,0.,0.).to_proto())},session_rust::proto::XformEntry{guid:"second".into(),xform:Some((&Xform::translation(1800.,0.,0.)*&Xform::scale_xyz(-0.8,1.2,1.4)).to_proto())}];let mut s=Scene::empty();crate::scene_document::import(&mut s,&proto.encode_to_vec(),"",&Xform::identity(),0.).unwrap();assert!(Rc::ptr_eq(&s.objects()[0].mesh,&s.objects()[1].mesh));assert_eq!(s.objects()[0].mesh.spacing,s.objects()[1].mesh.spacing);let original=source(&s);g.set_scene(&s,None);c.distance=6000.;c.radius=3000.;let m=matrix(&c);let before=pixels_at(&g,m);let uploads=g.stats()[0];let place=s.placement(s.objects()[0].id).unwrap();s.place(s.objects()[0].id,&Xform::translation(100.,0.,0.)*&place).unwrap();g.set_scene(&s,None);assert!(pixels_at(&g,m)!=before);s.place(s.objects()[0].id,place).unwrap();g.set_scene(&s,None);assert!(pixels_at(&g,m)==before);assert_eq!(g.stats()[0],uploads);assert_eq!(source(&s),original);export("shared-spacing",&s,&before);
}
